/bin/bash -lc "python3 -c 'from html.parser import HTMLParser; import glob,html,re,os
class P(HTMLParser):
 def __init__(self): super().__init__(); self.depth=0; self.ain=None; self.buf=[]; self.out=[]
 def handle_starttag(self,t,a):
  d=dict(a)
  if t==\"div\":
   if \"important-notice-main\" in d.get(\"class\",\"\"): self.depth=1
   elif self.depth: self.depth+=1
  if t==\"a\" and self.depth and self.ain is None: self.ain=d.get(\"href\"); self.buf=[]
 def handle_endtag(self,t):
  if t==\"a\" and self.ain is not None:
   x=re.sub(r\"\\\\s+\",\" \",html.unescape(\"\".join(self.buf))).strip()
   if x: self.out.append((x,self.ain))
   self.ain=None; self.buf=[]
  if t==\"div\" and self.depth: self.depth-=1
 def handle_data(self,d):
  if self.ain is not None: self.buf.append(d)
for f in sorted(glob.glob(os.path.join(\"/Users/d111879/Documents/Project/DEMO/Student/Student_mobile/sapp/research/agent_runs/madhya-pradesh-five-institutes/workspaces/indian-institute-of-management-indore/tmp/iim-indore.*\",\"iimidr_ac_in_programmes_executive_programmes_*\")):
 p=P(); p.feed(open(f,encoding=\"utf-8\").read()); print(\"===\",os.path.basename(f),\"===\"); seen=set()
 for x,u in p.out:
  if (x,u) not in seen: print(x,\"\\t\",u); seen.add((x,u))' "

